        /// <summary>
        /// Configures the HttpClients.
        /// </summary>
        /// <param name="builder"></param>
        /// <returns></returns>
        public HostConfiguration AddApiHttpClients(Action<IHttpClientBuilder>? builder = null)
        {
            return AddApiHttpClients((Action<IServiceProvider, HttpClient>?)null, builder);
        }

        /// <summary>
        /// Configures the HttpClients.
        /// </summary>
        /// <param name="client"></param>
        /// <param name="builder"></param>
        /// <returns></returns>
        public HostConfiguration AddApiHttpClients(
            Action<HttpClient>? client,
            Action<IHttpClientBuilder>? builder = null)
        {
            var wrapped = client != null ? new Action<IServiceProvider, HttpClient>((_, httpClient) =>
            {
                client(httpClient);
            }) : null;
            return AddApiHttpClients(wrapped, builder);
        }

        /// <summary>
        /// Configures the HttpClients.
        /// </summary>
        /// <param name="client"></param>
        /// <param name="builder"></param>
        /// <returns></returns>
        public HostConfiguration AddApiHttpClients(
            Action<IServiceProvider, HttpClient>? client,
            Action<IHttpClientBuilder>? builder = null)
        {
            if (client == null)
                client = (_, c) => c.BaseAddress = new Uri(ClientUtils.BASE_ADDRESS);

            List<IHttpClientBuilder> builders = new List<IHttpClientBuilder>();

            builders.Add(_services.AddHttpClient<IAlertsApi, AlertsApi>("Org.OpenAPITools.Api.IAlertsApi", client));
            builders.Add(_services.AddHttpClient<IApprovalRequestsApi, ApprovalRequestsApi>("Org.OpenAPITools.Api.IApprovalRequestsApi", client));
            builders.Add(_services.AddHttpClient<IBillableMetricsApi, BillableMetricsApi>("Org.OpenAPITools.Api.IBillableMetricsApi", client));
            builders.Add(_services.AddHttpClient<IContractsApi, ContractsApi>("Org.OpenAPITools.Api.IContractsApi", client));
            builders.Add(_services.AddHttpClient<ICreditsAndCommitsApi, CreditsAndCommitsApi>("Org.OpenAPITools.Api.ICreditsAndCommitsApi", client));
            builders.Add(_services.AddHttpClient<ICustomFieldsApi, CustomFieldsApi>("Org.OpenAPITools.Api.ICustomFieldsApi", client));
            builders.Add(_services.AddHttpClient<ICustomersApi, CustomersApi>("Org.OpenAPITools.Api.ICustomersApi", client));
            builders.Add(_services.AddHttpClient<IDefaultApi, DefaultApi>("Org.OpenAPITools.Api.IDefaultApi", client));
            builders.Add(_services.AddHttpClient<IInvoicesApi, InvoicesApi>("Org.OpenAPITools.Api.IInvoicesApi", client));
            builders.Add(_services.AddHttpClient<INamedSchedulesApi, NamedSchedulesApi>("Org.OpenAPITools.Api.INamedSchedulesApi", client));
            builders.Add(_services.AddHttpClient<INotificationsApi, NotificationsApi>("Org.OpenAPITools.Api.INotificationsApi", client));
            builders.Add(_services.AddHttpClient<IPackagesApi, PackagesApi>("Org.OpenAPITools.Api.IPackagesApi", client));
            builders.Add(_services.AddHttpClient<IProductsApi, ProductsApi>("Org.OpenAPITools.Api.IProductsApi", client));
            builders.Add(_services.AddHttpClient<IRateCardsApi, RateCardsApi>("Org.OpenAPITools.Api.IRateCardsApi", client));
            builders.Add(_services.AddHttpClient<ISecurityApi, SecurityApi>("Org.OpenAPITools.Api.ISecurityApi", client));
            builders.Add(_services.AddHttpClient<ISettingsApi, SettingsApi>("Org.OpenAPITools.Api.ISettingsApi", client));
            builders.Add(_services.AddHttpClient<IUsageApi, UsageApi>("Org.OpenAPITools.Api.IUsageApi", client));

            foreach (IHttpClientBuilder instance in builders)
            {
                bool suppressDefault = false;
                OnAddApiHttpClientBuilder(instance, builder, ref suppressDefault);
                if (!suppressDefault)
                    builder?.Invoke(instance);
            }

            HttpClientsAdded = true;

            return this;
        }

        /// <summary>
        /// Applies configuration to each HttpClient.
        /// Implement this partial method to prepend configuration, invoke <paramref name="userBuilder"/> at the
        /// desired position, and append further configuration. Set <paramref name="suppressDefault"/> to
        /// <c>true</c> when you invoke <paramref name="userBuilder"/> yourself to prevent a second invocation,
        /// or to ignore the user's builder entirely.
        /// If this method is not implemented, <paramref name="userBuilder"/> is invoked automatically.
        /// </summary>
        /// <param name="builder">The <see cref="IHttpClientBuilder"/> to configure.</param>
        /// <param name="userBuilder">The caller-supplied builder action, or <c>null</c> if none was provided.</param>
        /// <param name="suppressDefault">Set to <c>true</c> to prevent the default invocation of <paramref name="userBuilder"/>.</param>
        partial void OnAddApiHttpClientBuilder(IHttpClientBuilder builder, Action<IHttpClientBuilder>? userBuilder, ref bool suppressDefault);

        /// <summary>
        /// Called at the end of the constructor after all JSON converters and services are registered.
        /// Implement this partial method to further configure <c>_jsonOptions</c> or register additional singletons via <c>_services</c>.
        /// </summary>
        partial void OnHostConfigurationCreated();

        /// <summary>
